import{_ as o,o as c,c as d,a3 as a}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse(`{"title":"console 篇 - console 中的 '$'","description":"","frontmatter":{},"headers":[],"relativePath":"books/chrome-devtools/06-console-篇-console-中的-'$'.md","filePath":"books/chrome-devtools/06-console-篇-console-中的-'$'.md","lastUpdated":1794316978000}`),t={name:"books/chrome-devtools/06-console-篇-console-中的-'$'.md"};function l(s,e,r,n,i,p){return c(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="console-篇-console-中的" tabindex="-1">console 篇 - console 中的 &#39;$&#39; <a class="header-anchor" href="#console-篇-console-中的" aria-label="Permalink to &quot;console 篇 - console 中的 &#39;$&#39;&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p><code>$</code> 作为 <code>jQuery</code> 的选择器，承载了一代前端的太多记忆，但是你可能没有想到的是，在我们使用 <code>Dev Tools</code> 进行调试的时候，<code>$</code> 也有大放异彩的一天呢？</p><h2 id="_1-0" tabindex="-1">1. <code>$0</code> <a class="header-anchor" href="#_1-0" aria-label="Permalink to &quot;1. `$0`&quot;">​</a></h2><p>在 <code>Chrome</code> 的 <code>Elements</code> 面板中， <code>$0</code> 是对我们当前选中的 <code>html</code> 节点的引用。</p><p>理所当然，<code>$1</code> 是对上一次我们选择的节点的引用，<code>$2</code> 是对在那之前选择的节点的引用，等等。一直到 <code>$4</code></p><p>你可以尝试一些相关操作(例如: <code>$1.appendChild($0)</code>)</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/7/16785c75b56d3a80~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_1-和" tabindex="-1">1. <code>$</code> 和 <code>?</code> <a class="header-anchor" href="#_1-和" aria-label="Permalink to &quot;1. `$` 和 `?`&quot;">​</a></h2><p>如果你没有在 <code>App</code> 中定义过 <code>$</code> 变量 (例如 <code>jQuery</code> )的话，它在 <code>console</code> 中就是对这一大串函数 <code>document.querySelector</code> 的别名。</p><p>如果是 <code>?</code> 就更加厉害了，还能节省更多的时间，因为它不仅执行 <code>document.QuerySelectorAll</code> 并且它返回的是：一个节点的 <strong>数组</strong> ，而不是一个 <code>Node list</code></p><p>本质上来说 <code>Array.from(document.querySelectorAll(&#39;div&#39;)) === ?(&#39;div&#39;)</code> ，但是<code>document.querySelectorAll(&#39;div&#39;)</code> 和 <code>?(&#39;div&#39;)</code> 哪一种方式更加优雅呢？</p><h2 id="_2" tabindex="-1">2. <code>$_</code> <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2. `$_`&quot;">​</a></h2><p>调试的过程中，你经常会通过打印查看一些变量的值，但如果你想看一下上次执行的结果呢？再输一遍表达式吗？</p><p>这时候 <code>$_</code> 就派上了用场，<code>$_</code> 是对上次执行的结果的 <strong>引用</strong> ：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/7/16785d333e7c1d7f~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_3-i" tabindex="-1">3. <code>$i</code> <a class="header-anchor" href="#_3-i" aria-label="Permalink to &quot;3. `$i`&quot;">​</a></h2><p>现在的前端开发过程，离不开各种 <code>npm</code> 插件，但你可能没有想过，有一天我们竟然可以在 <code>Dev Tools</code> 里面来使用 <code>npm</code> 插件！</p><p>有时你只是想玩玩新出的 <code>npm</code> 包，现在不用再大费周章去建一个项目测试了，只需要在 <a href="https://chrome.google.com/webstore/detail/console-importer/hgajpakhafplebkdljleajgbpdmplhie/related" target="_blank" rel="noreferrer">Chrome插件:Console Importer</a> 的帮助之下，快速的在 <code>console</code> 中引入和测试一些 <code>npm</code> 库。</p><p>运行 <code>$i(&#39;lodash&#39;)</code> 或者 <code>$i(&#39;moment&#39;)</code> 几秒钟后，你就可以获取到 <code>lodash / momentjs</code> 了:</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/7/16785da0dea963fb~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p>',21)])])}const _=o(t,[["render",l]]);export{h as __pageData,_ as default};
